import React, { useEffect, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";
import { Link } from "react-router-dom";
import propertiesData from "../data/properties";
import Navbar from "../components/Navbar";

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png"),
  iconUrl: require("leaflet/dist/images/marker-icon.png"),
  shadowUrl: require("leaflet/dist/images/marker-shadow.png"),
});

export default function Home() {
  const [properties, setProperties] = useState(propertiesData);
  const [loading, setLoading] = useState(true);
  const [activeId, setActiveId] = useState(null);

  useEffect(() => {
    setTimeout(() => setLoading(false), 2000);
  }, []);

  const toggleLike = (id) => {
    setProperties(properties.map((p) => p.id === id ? { ...p, liked: !p.liked } : p));
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 transition-colors duration-300">

      <Navbar favoritesCount={properties.filter((p) => p.liked).length} />

      {/* ── HERO ── */}
      <div className="relative h-[320px] overflow-hidden">
        <img
          src="https://images.unsplash.com/photo-1584738766473-61c083514bf4?w=1800&q=85"
          alt="hero"
          className="w-full h-full object-cover object-center"
        />
        <div className="absolute inset-0 bg-gradient-to-r from-black/70 via-black/40 to-transparent" />

        <div className="absolute inset-0 flex flex-col justify-center px-8 md:px-16 max-w-3xl">
          <span className="bg-blue-600 text-white text-xs font-bold px-3 py-1 rounded-full mb-4 uppercase tracking-widest w-fit">
            República Dominicana
          </span>
          <h1 className="text-4xl md:text-5xl font-black text-white leading-tight mb-3 drop-shadow">
            Encuentra tu<br />hogar <span className="text-blue-400">ideal</span>
          </h1>
          <p className="text-gray-300 text-base mb-6 max-w-md">
            Miles de propiedades en venta y renta en todo el país
          </p>

          {/* SEARCH BAR */}
          <div className="w-full max-w-xl bg-white dark:bg-gray-800 rounded-2xl shadow-2xl p-1.5 flex gap-2">
            <input
              type="text"
              placeholder="🔍  Ciudad, sector o propiedad..."
              className="flex-1 px-4 py-2.5 outline-none bg-transparent text-gray-800 dark:text-gray-100 placeholder-gray-400 text-sm"
            />
            <button className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl font-semibold transition text-sm shrink-0">
              Buscar
            </button>
          </div>
        </div>

        {/* STATS — esquina inferior derecha */}
        <div className="absolute bottom-4 right-6 hidden md:flex gap-5 text-white text-sm">
          <div className="text-center">
            <p className="font-black text-xl">+2,400</p>
            <p className="text-gray-300 text-xs">Propiedades</p>
          </div>
          <div className="w-px bg-white/25" />
          <div className="text-center">
            <p className="font-black text-xl">+180</p>
            <p className="text-gray-300 text-xs">Agentes</p>
          </div>
          <div className="w-px bg-white/25" />
          <div className="text-center">
            <p className="font-black text-xl">+12</p>
            <p className="text-gray-300 text-xs">Ciudades</p>
          </div>
        </div>
      </div>

      {/* ── LAYOUT DOS COLUMNAS ── */}
      <div className="flex flex-col lg:flex-row h-auto lg:h-[calc(100vh-64px-320px)]">

        {/* COLUMNA IZQUIERDA — feed scrolleable */}
        <div className="flex-1 overflow-y-auto px-4 md:px-6 py-6 lg:max-w-[55%]">

          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="text-xl font-black text-gray-900 dark:text-white">Propiedades destacadas</h2>
              <p className="text-gray-400 text-sm">{properties.length} propiedades</p>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {loading ? (
              [...Array(6)].map((_, i) => (
                <div key={i} className="bg-white dark:bg-gray-800 rounded-3xl overflow-hidden animate-pulse">
                  <div className="h-44 bg-gray-300 dark:bg-gray-700" />
                  <div className="p-4 space-y-3">
                    <div className="h-4 bg-gray-300 dark:bg-gray-700 rounded w-3/4" />
                    <div className="h-3 bg-gray-200 dark:bg-gray-600 rounded w-1/2" />
                  </div>
                </div>
              ))
            ) : (
              properties.map((prop) => (
                <Link key={prop.id} to={`/property/${prop.id}`}>
                  <div
                    onMouseEnter={() => setActiveId(prop.id)}
                    onMouseLeave={() => setActiveId(null)}
                    className={`group bg-white dark:bg-gray-800 rounded-3xl overflow-hidden transition-all duration-300 border-2 cursor-pointer ${
                      activeId === prop.id
                        ? "border-blue-500 shadow-2xl scale-[1.02]"
                        : "border-transparent shadow hover:shadow-xl dark:border-gray-700"
                    }`}
                  >
                    {/* IMAGEN */}
                    <div className="relative overflow-hidden">
                      <img
                        src={prop.image}
                        alt={prop.title}
                        className="w-full h-44 object-cover group-hover:scale-105 transition-transform duration-500"
                      />
                      <div className="absolute top-3 left-3 flex gap-2">
                        <span className={`px-2.5 py-1 rounded-full text-xs font-bold shadow ${
                          prop.status === "Venta" ? "bg-blue-600 text-white" : "bg-green-500 text-white"
                        }`}>
                          {prop.status}
                        </span>
                        <span className="bg-white/90 dark:bg-gray-800/90 text-gray-700 dark:text-gray-200 px-2.5 py-1 rounded-full text-xs font-semibold shadow">
                          {prop.type}
                        </span>
                      </div>
                      <button
                        onClick={(e) => { e.preventDefault(); toggleLike(prop.id); }}
                        className="absolute top-3 right-3 bg-white dark:bg-gray-800 w-8 h-8 rounded-full flex items-center justify-center shadow hover:scale-110 transition-transform text-sm"
                      >
                        {prop.liked ? "❤️" : "🤍"}
                      </button>
                    </div>

                    {/* INFO */}
                    <div className="p-4">
                      <h3 className="font-bold text-gray-900 dark:text-white text-sm leading-snug">{prop.title}</h3>
                      <p className="text-gray-400 text-xs mt-0.5">📍 República Dominicana</p>
                      <p className="text-blue-600 dark:text-blue-400 font-black text-lg mt-1.5">
                        ${prop.price.toLocaleString()}
                        {prop.status === "Renta" && <span className="text-xs font-normal text-gray-400">/mes</span>}
                      </p>
                      <div className="flex gap-3 mt-2 pt-2 border-t border-gray-100 dark:border-gray-700 text-gray-400 text-xs">
                        <span>🛏️ {prop.rooms}</span>
                        <span>🛁 {prop.baths}</span>
                        <span>🚗 {prop.parking}</span>
                      </div>
                    </div>
                  </div>
                </Link>
              ))
            )}
          </div>
        </div>

        {/* COLUMNA DERECHA — mapa sticky */}
        <div className="hidden lg:block lg:flex-1 sticky top-[64px] h-[calc(100vh-64px-320px)]">
          <MapContainer
            center={[18.7357, -70.1627]}
            zoom={7}
            scrollWheelZoom={true}
            className="w-full h-full"
            style={{ zIndex: 0 }}
          >
            <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
            {properties.map((prop) => (
              <Marker key={prop.id} position={[prop.lat, prop.lng]}>
                <Popup>
                  <strong>{prop.title}</strong><br />
                  ${prop.price.toLocaleString()} · {prop.status}
                </Popup>
              </Marker>
            ))}
          </MapContainer>
        </div>

      </div>
    </div>
  );
}
